"""GELU and GELU-residual dispatch via the cubin bundle runtime.

Three families:
- `gelu_residual_bfloat16_h1024`: fused GELU(x) * (y + 1) at hidden=1024,
  single-variant bundle.
- `gelu`: exact or tanh-approximate GELU, keyed by last-dim and arithmetic.
- `gelu_add`: exact GELU with a repeating-row BF16 add epilogue.
  Unshipped variants fall back to PyTorch with a one-time warning.
"""


import torch
import torch.nn.functional as F

from kestrel_kernels.cubin_runtime import CubinFamily
from kestrel_kernels.fallback import ceil_div, is_cute_jit_enabled, warn_fallback_once
from kestrel_kernels.gelu_residual.fallback import gelu_residual_torch_into

_residual_family = CubinFamily("gelu_residual_bfloat16_h1024")
_gelu_family = CubinFamily("gelu")
_gelu_add_family = CubinFamily("gelu_add")
_ENABLE_JIT = is_cute_jit_enabled()
if _ENABLE_JIT:
    from scripts.precompile import cubin_bundles as _cubin_bundles


def _normalize_gelu_out(inp: torch.Tensor, out: torch.Tensor) -> torch.Tensor:
    """Reshape the caller's out buffer to match inp's logical shape if needed."""
    if out.shape == inp.shape:
        return out
    if out.numel() != inp.numel():
        raise ValueError(
            "gelu_cute out tensor must match the input shape or have the same number "
            f"of elements, got inp={tuple(inp.shape)} out={tuple(out.shape)}"
        )
    return out.view_as(inp)


# Hidden size baked into the shipped gelu_residual cubin bundle.
_GELU_RESIDUAL_HIDDEN = 1024

# GeluKernel tiles the D axis into blocks of (num_threads × out_per_vec) =
# 128 × 8 = 1024 elements. Runtime grid_y must match what the cubin was
# compiled with: ceil_div(dim, _GELU_D_ELEMS_PER_BLOCK).
_GELU_D_ELEMS_PER_BLOCK = 1024


def _ensure_residual_variant(x: torch.Tensor, interleaved: bool = False) -> bool:
    variant_key = "_interleaved" if interleaved else "_default"
    if _residual_family.is_available(variant_key):
        return True
    device_index = int(x.device.index or 0)
    if (variant_key, device_index) in _residual_family._handles:
        return True
    if not _ENABLE_JIT:
        return False
    compile_fn = (
        _cubin_bundles._compile_gelu_residual_bfloat16_h1024_interleaved
        if interleaved
        else _cubin_bundles._compile_gelu_residual_bfloat16_h1024
    )
    _cubin_bundles.jit_compile_and_install(
        family=_residual_family,
        variant_key=variant_key,
        compile_fn=compile_fn,
        block_x=128,
        device_index=device_index,
    )
    return True


def _ensure_gelu_variant(
    variant_key: str,
    x: torch.Tensor,
    dim: int,
    *,
    approximate: str = "none",
    require_packed: bool = False,
) -> bool:
    if _gelu_family.is_available(variant_key):
        return True
    if require_packed:
        return False
    device_index = int(x.device.index or 0)
    if (variant_key, device_index) in _gelu_family._handles:
        return True
    if not _ENABLE_JIT:
        return False
    _cubin_bundles.jit_compile_and_install(
        family=_gelu_family,
        variant_key=variant_key,
        compile_fn=_cubin_bundles._compile_gelu(
            dim=dim,
            approximate=approximate,
        ),
        block_x=128,
        device_index=device_index,
    )
    return True


def _ensure_gelu_add_variant(
    variant_key: str,
    x: torch.Tensor,
    dim: int,
    repeat_rows: int,
    *,
    require_packed: bool = False,
) -> bool:
    if _gelu_add_family.is_available(variant_key):
        return True
    if require_packed:
        return False
    device_index = int(x.device.index or 0)
    if (variant_key, device_index) in _gelu_add_family._handles:
        return True
    if not _ENABLE_JIT:
        return False
    _cubin_bundles.jit_compile_and_install(
        family=_gelu_add_family,
        variant_key=variant_key,
        compile_fn=_cubin_bundles._compile_gelu_add(
            dim=dim,
            repeat_rows=repeat_rows,
        ),
        block_x=128,
        device_index=device_index,
    )
    return True


def gelu_residual_cute(
    out: torch.Tensor, inp: torch.Tensor, *, interleaved: bool = False
) -> None:
    """GELU residual: out = gelu(gate) * (up + 1), out shape [..., H].

    Standard layout (interleaved=False): inp is [gate[0:H], up[0:H]], the
    half-split ordering, so gate=inp[..., :H] and up=inp[..., H:].

    Interleaved layout (interleaved=True): inp uses the Qwen/megakernel 8-row
    gate/up interleave [gate[0:8], up[0:8], gate[8:16], up[8:16], ...] so that
    one weight layout serves both the native and the megakernel path. The
    output is emitted in standard [0:H] order either way, so downstream (the
    down GEMM) is layout-agnostic.

    Dispatches the bf16 / H=1024 cubin built by `cubin_bundles.py`. Only that
    one shape is supported; callers using other shapes need to fall back to
    the torch reference (kestrel_kernels.gelu_residual.fallback).
    """
    if inp.dtype != torch.bfloat16 or out.dtype != torch.bfloat16:
        raise ValueError(
            f"gelu_residual_cute requires bfloat16, got out={out.dtype} inp={inp.dtype}"
        )
    if out.shape[-1] != _GELU_RESIDUAL_HIDDEN or inp.shape[-1] != 2 * _GELU_RESIDUAL_HIDDEN:
        raise ValueError(
            f"gelu_residual_cute only supports hidden={_GELU_RESIDUAL_HIDDEN}; "
            f"got out.shape={tuple(out.shape)} inp.shape={tuple(inp.shape)}"
        )
    if inp.ndim == 2:
        out2, inp2 = out, inp
    else:
        num_tokens = inp.numel() // inp.shape[-1]
        out2 = out.view(num_tokens, out.shape[-1])
        inp2 = inp.view(num_tokens, inp.shape[-1])

    if not _ensure_residual_variant(out2, interleaved=interleaved):
        warn_fallback_once(
            "gelu_residual_cute_no_cubin",
            "kestrel-kernels: no gelu_residual cubin bundle for the current "
            "CUDA architecture; using PyTorch fallback.",
        )
        gelu_residual_torch_into(out=out2, inp=inp2, interleaved=interleaved)
        return
    variant_key = "_interleaved" if interleaved else "_default"
    _residual_family.resolve_dispatch(
        out2, variant_key=variant_key, grid_x=out2.size(0)
    )(out2, inp2)


def gelu_cute(
    inp: torch.Tensor,
    out: torch.Tensor | None = None,
    *,
    add: torch.Tensor | None = None,
    require_native: bool = False,
    require_packed: bool = False,
    approximate: str = "none",
) -> torch.Tensor:
    """Exact or tanh-approximate GELU with an optional BF16 add epilogue.

    ``add`` must have shape ``[repeat_rows, inp.shape[-1]]``. The input is
    flattened across every leading dimension and row ``i`` receives
    ``add[i % repeat_rows]``. This preserves the two-op BF16 contract: GELU
    rounds to BF16 before the add, and the result rounds to BF16 again.
    """
    if approximate not in ("none", "tanh"):
        raise ValueError(f"unsupported GELU approximation: {approximate}")
    if add is not None and approximate != "none":
        raise ValueError("GELU add epilogues currently require approximate='none'")
    if inp.dtype != torch.bfloat16:
        raise ValueError(f"gelu_cute requires bfloat16, got {inp.dtype}")
    if inp.ndim == 0:
        raise ValueError("gelu_cute input must have at least one dimension")

    if out is None:
        out = torch.empty_like(inp)
    else:
        out = _normalize_gelu_out(inp, out)

    dim = inp.shape[-1]
    repeat_rows = None
    if add is not None:
        if add.ndim != 2 or add.shape[1] != dim:
            raise ValueError(
                "gelu_cute add tensor must have shape [repeat_rows, dim], got "
                f"{tuple(add.shape)} for dim={dim}"
            )
        if add.shape[0] <= 0:
            raise ValueError("gelu_cute add repeat_rows must be positive")
        if add.dtype != inp.dtype or add.device != inp.device:
            raise ValueError("gelu_cute add tensor must match input device and dtype")
        if not add.is_contiguous():
            raise ValueError("gelu_cute add tensor must be contiguous")
        repeat_rows = int(add.shape[0])

    if repeat_rows is None:
        suffix = "_tanh" if approximate == "tanh" else ""
        variant_key = f"d{dim}{suffix}"
        native_available = inp.is_cuda and _ensure_gelu_variant(
            variant_key,
            inp,
            dim,
            approximate=approximate,
            require_packed=require_packed,
        )
    else:
        variant_key = f"d{dim}_r{repeat_rows}"
        native_available = inp.is_cuda and _ensure_gelu_add_variant(
            variant_key,
            inp,
            dim,
            repeat_rows,
            require_packed=require_packed,
        )
    if not native_available:
        if require_native or require_packed:
            raise RuntimeError(
                "required packed/native GELU artifact did not resolve for "
                f"variant {variant_key}"
            )
        warn_fallback_once(
            f"gelu_cute_no_variant_{variant_key}",
            f"kestrel-kernels: no gelu cubin variant for dim={dim} "
            f"({variant_key}) on the current CUDA architecture; using "
            "PyTorch fallback.",
        )
        out.copy_(F.gelu(inp, approximate=approximate))
        if add is not None:
            out_rows = out.view(-1, dim)
            num_rows = out_rows.shape[0]
            full_rows = (num_rows // repeat_rows) * repeat_rows
            if full_rows:
                out_rows[:full_rows].view(-1, repeat_rows, dim).add_(add)
            if full_rows != num_rows:
                out_rows[full_rows:].add_(add[: num_rows - full_rows])
        return out

    if inp.ndim == 2:
        inp2, out2 = inp, out
    else:
        num_tokens = inp.numel() // dim
        inp2 = inp.view(num_tokens, dim)
        out2 = out.view(num_tokens, dim)
    grid_y = ceil_div(dim, _GELU_D_ELEMS_PER_BLOCK)
    family = _gelu_family if add is None else _gelu_add_family
    resolve_dispatch = (
        family.resolve_shipped_dispatch
        if require_packed else family.resolve_dispatch
    )
    dispatch = resolve_dispatch(
        inp2, variant_key=variant_key, grid_x=inp2.size(0), grid_y=grid_y,
    )
    if add is None:
        dispatch(out2, inp2)
    else:
        dispatch(out2, inp2, add)
    return out


__all__ = ["gelu_residual_cute", "gelu_cute"]
